import*as THREE from'three';import{Module,VisualJoint,materials}from'../../core/index.js';import{mesh}from'../../modeling/parts.js';import{ring,cappedThread}from'./connectors.js';import{spec}from'./dimensions.js';const tau=Math.PI*2;
function closedLathe(profile){const g=new THREE.LatheGeometry(profile,64),p=g.attributes.position,idx=g.index,keep=[],a=new THREE.Vector3(),b=new THREE.Vector3(),c=new THREE.Vector3();for(let f=0;f<idx.count;f+=3){a.fromBufferAttribute(p,idx.getX(f));b.fromBufferAttribute(p,idx.getX(f+1)).sub(a);c.fromBufferAttribute(p,idx.getX(f+2)).sub(a);if(b.cross(c).lengthSq()>1e-16)keep.push(idx.getX(f),idx.getX(f+1),idx.getX(f+2));}g.setIndex(keep);return g;}
/** Own U111-B supplied round-rod antenna;estimated105mm,not a rated dimension. */
export class Antenna extends Module{static meta={id:'m5stack.unit.nbiot2.antenna',name:'U111-B supplied round SMA antenna,estimated105mm',sku:'U111-B accessory',connector:'sma-female',physicalConnector:'sma-male',dimensionsInferred:true};build({angleDeg=0}={}){const fixed=new THREE.Group();fixed.name='NBIoT2 own antenna fixed SMA coupling neck fork and side axle';this.body.add(fixed);const black=materials.plastic(0x171c17,{roughness:.87}),rib=materials.plastic(0x2a3028,{roughness:.86}),metal=materials.metal(0xbbbdaf,{roughness:.45}),gold=materials.metal(0xc4ae62,{roughness:.43}),ptfe=materials.plastic(0xe3e2cf,{roughness:.83}),nut=ring(fixed,4.7,3.25,8.5,-5,black,'NBIoT2 own antenna open ordinary SMA male coupling'),lip=ring(fixed,4.0,3.175,.3,-5,metal,'NBIoT2 own antenna true annular mating lip');for(let i=0;i<36;i++){const a=i*tau/36,o=mesh(fixed,new THREE.BoxGeometry(.12,7.1,.12),rib,[Math.cos(a)*4.66,-.75,Math.sin(a)*4.66],'NBIoT2 own antenna real coupling knurl envelope');o.rotation.y=-a;}class Helix extends THREE.Curve{getPoint(t,v=new THREE.Vector3()){const a=t*tau*6;return v.set(Math.cos(a)*3.22,-4.7+t*4.7,Math.sin(a)*3.22);}}const thread=mesh(fixed,cappedThread(new Helix(),384,.065),metal,[0,0,0],'NBIoT2 own antenna internal closed-ended helical thread'),carrier=ring(fixed,3.1,.32,1.1,.3,ptfe,'NBIoT2 own antenna male dielectric carrier'),pin=mesh(fixed,new THREE.CylinderGeometry(.24,.24,3.9,32),gold,[0,-1.65,0],'NBIoT2 own antenna real exposed ordinary SMA male center pin'),pinTip=mesh(fixed,new THREE.ConeGeometry(.24,.35,32).rotateX(Math.PI),gold,[0,-3.775,0],'NBIoT2 own antenna center pin tip'),neck=mesh(fixed,new THREE.CylinderGeometry(3.3,3.8,7.5,48),black,[0,7.25,0],'NBIoT2 own antenna fixed molded neck'),collar=mesh(fixed,new THREE.CylinderGeometry(4.2,4.2,.8,48),rib,[0,3.7,0],'NBIoT2 own antenna fixed coupling collar'),cheeks=[];for(const sign of[-1,1])cheeks.push(mesh(fixed,new THREE.CylinderGeometry(3.0,3.0,.8,48).rotateZ(Math.PI/2),black,[sign*3.45,12,0],'NBIoT2 own antenna fixed fork cheek,profile inferred'));const axle=mesh(fixed,new THREE.CylinderGeometry(.8,.8,7.8,32).rotateZ(Math.PI/2),rib,[0,12,0],'NBIoT2 own antenna retained side-axis appearance,inferred datum'),moving=new THREE.Group();moving.name='NBIoT2 own antenna moving round radome and elbow';const knuckle=mesh(moving,new THREE.CylinderGeometry(2.7,2.7,6.1,48).rotateZ(Math.PI/2),black,[0,0,0],'NBIoT2 own antenna moving elbow barrel,shape inferred'),profile=[[0,0],[2.6,0],[3.2,4],[3.25,10],[3.1,78],[2.95,85],[2.6,87.6],[0,88]].map(p=>new THREE.Vector2(...p)),rod=mesh(moving,closedLathe(profile),black,[0,0,0],'NBIoT2 own estimated105mm round tapered solid radome,no borrowed flattened profile');const tilt=this.add(new VisualJoint({id:'tilt',label:'U111-B own antenna visual elbow angle',position:spec.antenna.pivot,axis:spec.antenna.axis,limitsDeg:spec.antenna.limitsDeg,meta:{visualRangeDeg:[0,90],rangeEvidence:spec.antenna.rangeEvidence,scope:'Externally requested relative angle only;own approx105mm round-rod estimate,axis/profile/range inferred.Not measured stops,automatic sweep,continuous spin,unscrewing,RF/network/power/electrical orfirmware behavior'}}));tilt.object3d.add(moving);tilt.set({angleDeg});this.antennaAssembly={fixed,nut,lip,thread,carrier,pin,pinTip,neck,collar,cheeks,axle,moving,knuckle,rod,tilt};}}
